func sha12Hex(input string) string {
	sum := sha256.Sum256([]byte(input))
	return hex.EncodeToString(sum[:])[:12]
}

func appendTLSExt(exts []byte, extType uint16, data []byte) []byte {
	exts = append(exts, byte(extType>>8), byte(extType))
	exts = append(exts, byte(len(data)>>8), byte(len(data)))
	exts = append(exts, data...)
	return exts
}

func buildTLSClientHelloForVersionTest(supportedVersions []byte) []byte {
	body := make([]byte, 0, 128)
	body = append(body, 0x03, 0x03)          // legacy_version
	body = append(body, make([]byte, 32)...) // random
	body = append(body, 0x00)                // session_id_len
	body = append(body,
		0x00, 0x02, // cipher_suites_len
		0x13, 0x01, // TLS_AES_128_GCM_SHA256
		0x01, 0x00, // compression_methods_len + null compression
	)

	exts := make([]byte, 0, 32)
	exts = appendTLSExt(exts, 0x002b, supportedVersions) // supported_versions
	body = append(body, byte(len(exts)>>8), byte(len(exts)))
	body = append(body, exts...)

	handshake := make([]byte, 0, 4+len(body))
	handshake = append(handshake, 0x01) // client hello
	handshake = append(handshake, byte(len(body)>>16), byte(len(body)>>8), byte(len(body)))
	handshake = append(handshake, body...)

	record := make([]byte, 0, 5+len(handshake))
	record = append(record, 0x16, 0x03, 0x01, byte(len(handshake)>>8), byte(len(handshake)))
	record = append(record, handshake...)
	return record
}

func buildSNIExtension(domain string) []byte {
	name := []byte(domain)
	nameList := make([]byte, 0, 1+2+len(name))
	nameList = append(nameList, 0x00) // host_name
	nameList = append(nameList, byte(len(name)>>8), byte(len(name)))
	nameList = append(nameList, name...)
	extData := make([]byte, 0, 2+len(nameList))
	extData = append(extData, byte(len(nameList)>>8), byte(len(nameList)))
	extData = append(extData, nameList...)
	return extData
}

func buildTLSClientHelloWithExtensions(exts []byte) []byte {
	body := make([]byte, 0, 128)
	body = append(body, 0x03, 0x03)          // legacy_version
	body = append(body, make([]byte, 32)...) // random
	body = append(body, 0x00)                // session_id_len
	body = append(body,
		0x00, 0x02, // cipher_suites_len
		0x13, 0x01, // TLS_AES_128_GCM_SHA256
		0x01, 0x00, // compression_methods_len + null compression
	)
	body = append(body, byte(len(exts)>>8), byte(len(exts)))
	body = append(body, exts...)

	handshake := make([]byte, 0, 4+len(body))
	handshake = append(handshake, 0x01) // client hello
	handshake = append(handshake, byte(len(body)>>16), byte(len(body)>>8), byte(len(body)))
	handshake = append(handshake, body...)

	record := make([]byte, 0, 5+len(handshake))
	record = append(record, 0x16, 0x03, 0x01, byte(len(handshake)>>8), byte(len(handshake)))
	record = append(record, handshake...)
	return record
}

